import{_ as r,c as o,o as e,b0 as t}from"./chunks/framework.Dmsv_Tiv.js";const l="/media-docs/assets/13592964838270458197.DScl6lR6.jpg",i="/media-docs/assets/15838501711951003943.vY1WlaDW.jpg",s="/media-docs/assets/16270943030697101257.BPuRjUFn.jpg",b=JSON.parse('{"title":"LV010-Camera接口简介","description":null,"frontmatter":{"title":"LV010-Camera接口简介","date":"2025-10-30T14:50:24.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/camera/cam-basic/126b0f7548003c96372b86c0","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-30T14:50:24.969Z","fulluuid":"6372b86c0cc045d0885fe845baa01c1f","useduuid":"6372b86c0"}},"headers":[],"relativePath":"sdoc/camera/cam-basic/126b0f7548003c96372b86c0.md","filePath":"sdoc/05-Camera/01-Camera基础/LV010-Camera接口简介.md","lastUpdated":1767537778000}'),n={name:"sdoc/camera/cam-basic/126b0f7548003c96372b86c0.md"};function c(p,a,d,h,u,g){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="lv010-camera接口简介" tabindex="-1">LV010-Camera接口简介 <a class="header-anchor" href="#lv010-camera接口简介" aria-label="Permalink to &quot;LV010-Camera接口简介&quot;">​</a></h1><p>这部分简单了解一下摄像头的一些协议和接口。</p><h2 id="一、摄像头接口协议" tabindex="-1">一、摄像头接口协议 <a class="header-anchor" href="#一、摄像头接口协议" aria-label="Permalink to &quot;一、摄像头接口协议&quot;">​</a></h2><p>摄像头接口的协议类型多种多样，每种协议都有其特定的应用场景和优势。以下是一些常见的摄像头接口协议类型，简单了解一下。</p><h3 id="_1-dvp-digital-video-port" tabindex="-1">1. DVP（Digital Video Port） <a class="header-anchor" href="#_1-dvp-digital-video-port" aria-label="Permalink to &quot;1. DVP（Digital Video Port）&quot;">​</a></h3><p>DVP（Digital Video Port）摄像头接口是一种数字视频接口标准，主要用于传输和接收数字视频数据。它采用 <strong>并行传输</strong> 方式，通过多个数据线同时传输视频像素数据，具有高速、实时和低延迟的特点。具备高速传输，稳定性好，成本低廉，支持多种数据位宽，支持直接存储器访问（DMA）丰富的图像控制功能。</p><p>常用于监控系统、消费电子产品、手术室、诊所以及其他医疗环境。</p><h3 id="_2-usb-universal-serial-bus" tabindex="-1">2. USB（Universal Serial Bus） <a class="header-anchor" href="#_2-usb-universal-serial-bus" aria-label="Permalink to &quot;2. USB（Universal Serial Bus）&quot;">​</a></h3><p>USB 是一种通用的串行总线接口协议，广泛用于连接计算机和外部设备。基于 USB 协议的摄像头可以通过 USB 接口连接到计算机，进行数据传输和通信，常用的就是 usb 中的 uvc 协议。</p><h3 id="_3-rtsp-real-time-streaming-protocol" tabindex="-1">3. RTSP（Real-Time Streaming Protocol） <a class="header-anchor" href="#_3-rtsp-real-time-streaming-protocol" aria-label="Permalink to &quot;3. RTSP（Real-Time Streaming Protocol）&quot;">​</a></h3><p>RTSP 是一种用于实时媒体流传输的协议，常用于视频监控领域。摄像头可以通过 RTSP 协议将实时的视频流传输给接收端，接收端可以通过相应的软件进行实时播放或录制。</p><p>支持实时流传输，适合视频监控和流媒体应用。</p><h3 id="_4-rtp-real-time-transport-protocol" tabindex="-1">4. RTP（Real-time Transport Protocol） <a class="header-anchor" href="#_4-rtp-real-time-transport-protocol" aria-label="Permalink to &quot;4. RTP（Real-time Transport Protocol）&quot;">​</a></h3><p>RTP 是一种用于实时媒体数据传输的协议，常用于视频会议、流媒体等场景。摄像头可以通过 RTP 协议将视频数据进行分片和传输，接收端可以根据 RTP 协议进行数据的解析和播放。</p><p>支持实时数据传输，适用于需要低延迟的应用场景。</p><h3 id="_5-mipi-mobile-industry-processor-interface" tabindex="-1">5. MIPI（Mobile Industry Processor Interface） <a class="header-anchor" href="#_5-mipi-mobile-industry-processor-interface" aria-label="Permalink to &quot;5. MIPI（Mobile Industry Processor Interface）&quot;">​</a></h3><p>MIPI 是一个由 ARM、Nokia、ST、TI 等公司成立的<strong>联盟</strong>，旨在标准化手机内部的接口，如摄像头接口 CSI 等。CSI（Camera Serial Interface）是 MIPI 联盟定义的一个标准，用于连接 CPU 和摄像模组之间的高速串行接口。</p><p>MIPI 摄像头在嵌入式产品中，比如行车记录仪、执法仪、高清微型相机、网络监控相机等得到广泛应用。</p><blockquote><p>注意：这个是后面学习的重点，会再详细学习，这里只是简单介绍。</p></blockquote><h2 id="二、接口类型" tabindex="-1">二、接口类型 <a class="header-anchor" href="#二、接口类型" aria-label="Permalink to &quot;二、接口类型&quot;">​</a></h2><h3 id="_1-消费级-通用接口" tabindex="-1">1. 消费级/通用接口 <a class="header-anchor" href="#_1-消费级-通用接口" aria-label="Permalink to &quot;1. 消费级/通用接口&quot;">​</a></h3><h4 id="_1-1-usb-接口" tabindex="-1">1.1 USB 接口 <a class="header-anchor" href="#_1-1-usb-接口" aria-label="Permalink to &quot;1.1 USB 接口&quot;">​</a></h4><p>USB 接口，只有数据线，没有时钟线。USB 是异步串行接口。使用的是 uvc 协议。是目前最常见的摄像头接口类型之一，广泛应用于桌面电脑、笔记本电脑等主流设备。</p><p><strong>特点</strong></p><ul><li><strong>广泛兼容性</strong>：USB 接口几乎在所有现代电脑和笔记本电脑上都可用，无需额外的硬件支持。</li><li><strong>即插即用</strong>：大多数 USB 摄像头无需安装额外的驱动程序，只需插入 USB 端口即可使用。</li><li><strong>数据传输速度</strong>：USB 2.0 提供最高 480 Mbps 的传输速度，而 USB 3.0 和 USB 3.1 则分别提供高达 5 Gbps 和 10 Gbps 的速度。对于摄像头来说，USB 3.0 及以上版本更适合高清视频传输。</li></ul><h4 id="_1-2-hdmi-接口" tabindex="-1">1.2 HDMI 接口 <a class="header-anchor" href="#_1-2-hdmi-接口" aria-label="Permalink to &quot;1.2  HDMI 接口&quot;">​</a></h4><p>HDMI 是高清晰度多媒体接口的缩写，常用于高清电视、投影仪、监视器等设备。</p><p><strong>特点</strong></p><ul><li><strong>高清传输</strong>：HDMI 支持高达 4K 和 8K 的分辨率，提供清晰、高质量的图像。</li><li><strong>音视频同传</strong>：HDMI 接口可以同时传输音频和视频信号，无需额外的线缆。</li><li><strong>长距离传输限制</strong>：HDMI 接口通常用于短距离传输，例如从电脑到显示器或电视。虽然 HDMI 2.0 和 HDMI 2.1 支持更长的线缆，但传输质量可能受到影响。</li></ul><h3 id="_2-网络与安防监控接口" tabindex="-1">2. 网络与安防监控接口 <a class="header-anchor" href="#_2-网络与安防监控接口" aria-label="Permalink to &quot;2. 网络与安防监控接口&quot;">​</a></h3><h4 id="_2-1-bnc-接口" tabindex="-1">2.1 BNC 接口 <a class="header-anchor" href="#_2-1-bnc-接口" aria-label="Permalink to &quot;2.1 BNC 接口&quot;">​</a></h4><p>BNC（Bayonet Neill–Concelman）接口是一种同轴电缆连接器，常用于模拟视频传输，BNC 接头是监控工程中用于摄像设备输出时导线和摄像机的连接头。有别于普通 15 针 D-SUB 标准接头的特殊显示器接口（VGA 接口也叫 D-Sub 接口）。由 RGB 三原色信号及行同步、场同步五个独立信号接头组成。</p><img src="'+l+'" alt="img" style="zoom:50%;"><p><strong>特点</strong></p><ul><li><strong>模拟视频传输</strong>：BNC 接口主要用于传输模拟视频信号，如 CCTV（闭路电视）系统。</li><li><strong>长距离传输</strong>：BNC 接口可以支持长距离的视频传输，而信号质量相对稳定。</li><li><strong>逐渐淘汰</strong>：随着数字技术的普及，BNC 接口在现代摄像头和监控系统中逐渐被淘汰。</li></ul><h4 id="_2-2-rj45-接口" tabindex="-1">2.2 RJ45 接口 <a class="header-anchor" href="#_2-2-rj45-接口" aria-label="Permalink to &quot;2.2 RJ45 接口&quot;">​</a></h4><p>RJ45 接口，也称为以太网接口，通常用于网络连接，但在某些情况下也用于网络摄像头。</p><img src="'+i+'" alt="img" style="zoom:67%;"><ul><li><strong>网络连接</strong>：RJ45 接口允许摄像头直接连接到网络，无需额外的网络适配器。</li><li><strong>PoE 支持</strong>：许多网络摄像头支持 PoE（Power over Ethernet），这意味着它们可以通过同一根网线同时接收数据和电力。</li><li><strong>传输距离</strong>：使用适当的网络设备（如交换机和路由器），RJ45 接口可以实现长距离的视频传输。</li></ul><h4 id="_2-3-poe-接口" tabindex="-1">2.3 POE 接口 <a class="header-anchor" href="#_2-3-poe-接口" aria-label="Permalink to &quot;2.3 POE 接口&quot;">​</a></h4><p>POE 是一种特殊的网络接口，允许通过网线同时为摄像头提供网络信号和电力供应。（其实与 RJ45 接口是一样，就是多了供电线）。</p><p><strong>特点</strong></p><ul><li><strong>简化安装</strong>：POE 技术减少了对独立电源线的需求，从而简化了摄像头的安装过程。</li><li><strong>节能</strong>：由于电力和数据通过同一根电缆传输，POE 技术还可以减少能源消耗。</li><li><strong>兼容性</strong>：POE 接口与标准以太网接口兼容，因此可以与大多数网络设备一起使用。</li></ul><h4 id="_2-3-av-接口" tabindex="-1">2.3 AV 接口 <a class="header-anchor" href="#_2-3-av-接口" aria-label="Permalink to &quot;2.3 AV 接口&quot;">​</a></h4><p>AV 接口是一种常见的模拟视频接口类型，也被用于摄像头的连接。AV 接口的摄像头可以通过视频信号输入和输出接口，实现视频拍摄和输出，适用于家庭摄影、录像等场景。</p><p>AV 接口是音频（Audio）和视频（Video）分离传输的接口，主要由三个独立的 RCA 插头组成。</p><ul><li><strong>V 接口</strong>：连接混合视频信号，通常为黄色插口。</li><li><strong>L 接口</strong>：连接左声道声音信号，通常为白色插口。</li><li><strong>R 接口</strong>：连接右声道声音信号，通常为红色插口。</li></ul><img src="'+s+'" alt="img" style="zoom:80%;"><p><strong>特点</strong></p><ul><li><strong>音视频分离传输</strong>：AV 接口将音频和视频信号分开传输，避免了因音视频混合干扰而导致的图像质量下降。这种分离传输的方式确保了信号的纯净性和稳定性，从而提供了更好的视听体验。</li><li><strong>兼容性强</strong>：AV 接口广泛应用于各种音视频设备，如电视、DVD 播放器、游戏机等。它具有良好的兼容性，可以方便地将这些设备与电视机或其他显示设备连接起来，实现音视频的播放和分享。</li><li><strong>操作简便</strong>：使用 AV 接口进行连接时，只需使用相应的线缆将设备的 AV 接口连接起来即可。这种连接方式简单易懂，不需要复杂的设置和操作，适合普通用户的使用需求。</li><li><strong>成本较低</strong>：相对于一些其他的高清接口来说，AV 接口的制造成本较低，因此设备的售价也会相对较低。这使得更多的用户可以享受到高质量的音视频体验。</li><li><strong>支持多种格式</strong>：AV 接口支持多种音视频格式的输出和输入，可以满足不同设备和内容的需求。无论是标清还是高清的音视频信号，都可以通过 AV 接口进行传输和处理。</li></ul><h3 id="_3-嵌入式与移动设备接口" tabindex="-1">3. 嵌入式与移动设备接口 <a class="header-anchor" href="#_3-嵌入式与移动设备接口" aria-label="Permalink to &quot;3. 嵌入式与移动设备接口&quot;">​</a></h3><h4 id="_3-1-mipi-csi-接口" tabindex="-1">3.1 MIPI CSI 接口 <a class="header-anchor" href="#_3-1-mipi-csi-接口" aria-label="Permalink to &quot;3.1 MIPI CSI 接口&quot;">​</a></h4><p>MIPI (Mobile Industry Processor Interface) 是 2003 年由 ARM, Nokia, ST , TI 等公司成立的一个联盟，目的是把手机内部的接口如摄像头、显示屏接口、射频/基带接口等标准化，从而减少手机设计的复杂程度和增加设计灵活性。</p><p>MIPI 联盟下面有不同的 WorkGroup，分别定义了一系列的手机内部接口标准，比如</p><ul><li><p><strong>DSI（Display Serial Interface）</strong>：用于连接显示屏和处理器，提供高带宽的串行数据传输，主要用于手机、平板电脑等移动设备的显示屏。通常还有一个独立的差分时钟通道。</p></li><li><p><strong>CSI（Camera Serial Interface）</strong>：用于连接摄像头模块和处理器，支持高带宽的数据传输，常用于移动设备的摄像头。</p></li></ul><h4 id="_3-2-dvp-接口" tabindex="-1">3.2 DVP 接口 <a class="header-anchor" href="#_3-2-dvp-接口" aria-label="Permalink to &quot;3.2 DVP 接口&quot;">​</a></h4><p>DVP 的物理接口通常是一个 <strong>板对板连接器（Board-to-Board Connector）</strong> 或 <strong>FPC（柔性电路板）连接器</strong>。常见的引脚数量有 <strong>20 针、24 针、30 针</strong> 等。我们可以在摄像头模组的排线和主板的对应位置上看到这个具体的连接器。</p><p>它使用多条数据线同时传输像素数据。例如，对于 8 位数据总线，有 8 根数据线，在每个像素时钟的边沿，这 8 根线同时传输一个字节（8 个比特）的数据。还需要独立的像素时钟、行同步、场同步（或数据有效）等控制信号线。</p><blockquote><p>参考资料：</p><p><a href="https://blob.wenxiaobai.com/article/18278b40-f101-49d8-2d8b-030a061d4ebb" target="_blank" rel="noreferrer">硬件实用技巧：摄像头常用的输出协议类型和输出接口类型</a></p><p><a href="https://www.cnblogs.com/bujidao1128/p/18354671" target="_blank" rel="noreferrer">硬件接口之 MIPI - bujidao1128 - 博客园</a></p></blockquote>',59)])])}const P=r(n,[["render",c]]);export{b as __pageData,P as default};
